/** نواة_قيمة 안의 연결형 بايت_قيمة بث_قيمة. Ethernet/TCP 패킷 스택이 아닌 루프백 socket طبقة_قيمة. */
public final class بث_شبكة {
    static int[] حالة_قيمة = new int[16], منفذ_قيمة = new int[16], 짝 = new int[16], نظير_منفذ = new int[16], انتظر_قيمة = new int[16], أنظمة_المعلومات_حدود = new int[16];
    static int[] الكاميرا_الأمامية_قيمة = new int[16], رقم = new int[16], بيانات = new int[16 * 1024];
    static int التالي_عنصر = 50000;
    static int يتحقق(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && حالة_قيمة[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int رقم_المنفذ) { for (int يكرر_فهرس = 0; يكرر_فهرس < 16; يكرر_فهرس++) if (حالة_قيمة[يكرر_فهرس] != 0 && أنظمة_المعلومات_حدود[يكرر_فهرس] != 0 && منفذ_قيمة[يكرر_فهرس] == رقم_المنفذ) return true; return false; }
    public static int فتح_إدخال() {
        for (int يكرر_فهرس = 0; يكرر_فهرس < 16; يكرر_فهرس++) if (حالة_قيمة[يكرر_فهرس] == 0) { حالة_قيمة[يكرر_فهرس] = 1; نظير_منفذ[يكرر_فهرس] = منفذ_قيمة[يكرر_فهرس] = الكاميرا_الأمامية_قيمة[يكرر_فهرس] = رقم[يكرر_فهرس] = انتظر_قيمة[يكرر_فهرس] = أنظمة_المعلومات_حدود[يكرر_فهرس] = 0; 짝[يكرر_فهرس] = -1; return يكرر_فهرس + 40; }
        return -24;
    }
    public static int يربط_المشارك(int 열린파일번호, int مأخذ_التوصيل_عنوان, int رقم_المنفذ) {
        int يكرر_فهرس = يتحقق(열린파일번호); if (يكرر_فهرس < 0) return -9;
        if (مأخذ_التوصيل_عنوان != 0 && مأخذ_التوصيل_عنوان != 0x7f000001) return -99;
        if (حالة_قيمة[يكرر_فهرس] != 1 || رقم_المنفذ < 0 || رقم_المنفذ > 65535) return -22;
        if (رقم_المنفذ == 0) { do { رقم_المنفذ = التالي_عنصر++; if (التالي_عنصر > 65535) التالي_عنصر = 50000; } while (사용중(رقم_المنفذ)); }
        if (사용중(رقم_المنفذ)) return -98; منفذ_قيمة[يكرر_فهرس] = رقم_المنفذ; أنظمة_المعلومات_حدود[يكرر_فهرس] = 1; حالة_قيمة[يكرر_فهرس] = 2; return 0;
    }
    public static int انصات_المشارك(int 열린파일번호, int تراكم) { int يكرر_فهرس = يتحقق(열린파일번호); if (يكرر_فهرس < 0) return -9; if (حالة_قيمة[يكرر_فهرس] != 2 || تراكم < 1) return -22; حالة_قيمة[يكرر_فهرس] = 3; return 0; }
    public static int اتصال(int 열린파일번호, int مأخذ_التوصيل_عنوان, int رقم_المنفذ) {
        int يكرر_فهرس = يتحقق(열린파일번호); if (يكرر_فهرس < 0) return -9; if (مأخذ_التوصيل_عنوان != 0x7f000001) return -101;
        if (رقم_المنفذ < 1 || رقم_المنفذ > 65535 || حالة_قيمة[يكرر_فهرس] > 2) return -22;
        int يستلم_صفحة = -1; for (int صلة_داخلية_منصب = 0; صلة_داخلية_منصب < 16; صلة_داخلية_منصب++) if (حالة_قيمة[صلة_داخلية_منصب] == 3 && منفذ_قيمة[صلة_داخلية_منصب] == رقم_المنفذ) يستلم_صفحة = صلة_داخلية_منصب;
        if (يستلم_صفحة < 0) return -111;
        int 대기여부 = 0; for (int صلة_داخلية_منصب = 0; صلة_داخلية_منصب < 16; صلة_داخلية_منصب++) if (انتظر_قيمة[صلة_داخلية_منصب] == يستلم_صفحة + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (حالة_قيمة[يكرر_فهرس] == 1) { int 처리값 = يربط_المشارك(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int 다른번호 = فتح_إدخال(); if (다른번호 < 0) return 다른번호; 다른번호 -= 40;
        حالة_قيمة[يكرر_فهرس] = حالة_قيمة[다른번호] = 4; 짝[يكرر_فهرس] = 다른번호; 짝[다른번호] = يكرر_فهرس; منفذ_قيمة[다른번호] = رقم_المنفذ; نظير_منفذ[يكرر_فهرس] = رقم_المنفذ; نظير_منفذ[다른번호] = منفذ_قيمة[يكرر_فهرس]; انتظر_قيمة[다른번호] = يستلم_صفحة + 1; return 0;
    }
    public static int قبول_صديق(int 열린파일번호) { int يكرر_فهرس = يتحقق(열린파일번호); if (يكرر_فهرس < 0) return -9; if (حالة_قيمة[يكرر_فهرس] != 3) return -22; for (int صلة_داخلية_منصب = 0; صلة_داخلية_منصب < 16; صلة_داخلية_منصب++) if (حالة_قيمة[صلة_داخلية_منصب] != 0 && انتظر_قيمة[صلة_داخلية_منصب] == يكرر_فهرس + 1) { انتظر_قيمة[صلة_داخلية_منصب] = 0; return صلة_داخلية_منصب + 40; } return -11; }
    public static int كتابة(int 열린파일번호, int 항목수) {
        int يكرر_فهرس = يتحقق(열린파일번호); if (يكرر_فهرس < 0) return -9; if (حالة_قيمة[يكرر_فهرس] != 4) return -107;
        if (항목수 < 0 || 항목수 > 512) return -22; if (항목수 == 0) return 0;
        int صلة_داخلية_منصب = 짝[يكرر_فهرس]; if (صلة_داخلية_منصب < 0) return -32; int 총수 = 1024 - رقم[صلة_داخلية_منصب]; if (총수 == 0) return -11; if (총수 > 항목수) 총수 = 항목수;
        for (int مقارنة_منصب = 0; مقارنة_منصب < 총수; مقارنة_منصب++) بيانات[صلة_داخلية_منصب * 1024 + (الكاميرا_الأمامية_قيمة[صلة_داخلية_منصب] + رقم[صلة_داخلية_منصب] + مقارنة_منصب) % 1024] = استرجاع_شبكة.تحويل_قيمة_24592b8a[مقارنة_منصب]; رقم[صلة_داخلية_منصب] += 총수; return 총수;
    }
    public static int قراءة(int 열린파일번호, int 항목수) {
        int يكرر_فهرس = يتحقق(열린파일번호); if (يكرر_فهرس < 0) return -9; if (حالة_قيمة[يكرر_فهرس] != 4) return -107; if (항목수 < 0 || 항목수 > 512) return -22;
        if (항목수 == 0) return 0; if (رقم[يكرر_فهرس] == 0) return 짝[يكرر_فهرس] < 0 ? 0 : -11; if (항목수 > رقم[يكرر_فهرس]) 항목수 = رقم[يكرر_فهرس];
        for (int مقارنة_منصب = 0; مقارنة_منصب < 항목수; مقارنة_منصب++) استرجاع_شبكة.تحويل_قيمة_24592b8a[مقارنة_منصب] = بيانات[يكرر_فهرس * 1024 + (الكاميرا_الأمامية_قيمة[يكرر_فهرس] + مقارنة_منصب) % 1024]; الكاميرا_الأمامية_قيمة[يكرر_فهرس] = (الكاميرا_الأمامية_قيمة[يكرر_فهرس] + 항목수) % 1024; رقم[يكرر_فهرس] -= 항목수; return 항목수;
    }
    public static int يقرأ_المشارك_منفذ(int 열린파일번호) { int يكرر_فهرس = يتحقق(열린파일번호); return يكرر_فهرس < 0 ? -9 : منفذ_قيمة[يكرر_فهرس]; }
    public static int يقرأ_نظير_منفذ(int 열린파일번호) { int يكرر_فهرس = يتحقق(열린파일번호); return يكرر_فهرس < 0 ? -9 : نظير_منفذ[يكرر_فهرس]; }
    public static int إغلاق(int 열린파일번호) {
        int يكرر_فهرس = يتحقق(열린파일번호); if (يكرر_فهرس < 0) return -9;
        if (حالة_قيمة[يكرر_فهرس] == 3) for (int صلة_داخلية_منصب = 0; صلة_داخلية_منصب < 16; صلة_داخلية_منصب++) if (انتظر_قيمة[صلة_داخلية_منصب] == يكرر_فهرس + 1) { if (짝[صلة_داخلية_منصب] >= 0) 짝[짝[صلة_داخلية_منصب]] = -1; حالة_قيمة[صلة_داخلية_منصب] = انتظر_قيمة[صلة_داخلية_منصب] = أنظمة_المعلومات_حدود[صلة_داخلية_منصب] = 0; }
        if (짝[يكرر_فهرس] >= 0) 짝[짝[يكرر_فهرس]] = -1; حالة_قيمة[يكرر_فهرس] = أنظمة_المعلومات_حدود[يكرر_فهرس] = رقم[يكرر_فهرس] = انتظر_قيمة[يكرر_فهرس] = 0; return 0;
    }
}
